"""Demonstrate phase access rules and deny unqualified saved handoffs."""
import hashlib,json,html
from pathlib import Path
from dataclasses import asdict
from temporal_two_hand_coordinator_20261106 import Coordinator,Observation,Phase,Plan

R=Path(__file__).resolve().parent;O=R/'right_hand_rotation_20261105/canonical_body_grip'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def plan(entry='A',exit='B'):
    return Plan('a'*64,entry,exit,'synthetic-common-frame',90,{p.value:20. for p in (Phase.ROTATE,Phase.REGRASP,Phase.APPROACH,Phase.TURN,Phase.RETREAT)})
def obs(t,ready=True,gap=1.,pose=True):
    return Observation(t,frozenset(range(1,17)),True,ready,ready,ready,pose,gap,'synthetic-common-frame')
def main():
    c=Coordinator('A');intents=[];current=c.start(plan(),0,left_clear_confirmed=True)[0];intents.append(asdict(current));current=c.receive(current.token,'rotation_complete',1,obs(1,False,gap=-5.),left_clear_confirmed=True)[0];intents.append(asdict(current));current=c.receive(current.token,'lower_grip_and_upper_space_ready',2,obs(2),left_clear_confirmed=True)[0];intents.append(asdict(current));current=c.receive(current.token,'at_turn_start',3,obs(3))[0];intents.append(asdict(current));current=c.receive(current.token,'layer_turn_complete',4,obs(4))[0];intents.append(asdict(current));c.receive(current.token,'left_clear_of_cube',5,obs(5),left_clear_confirmed=True);assert c.phase==Phase.READY and c.left_clear
    denials=[]
    for label,path in (('89deg_grip_upper_space_blocked',O/'countergrip_level/seed0_source1_lift2_normal1.5_n850/review.json'),('83deg_temporary_hold_pose_unqualified',O/'temporary_handoff_load/review.json')):
        raw=json.loads(path.read_bytes())
        if label.startswith('89'):
            gap=raw['recorded_goal_replay']['settled_tail']['minimum_separating_plane_gap_1ms_mm'];pose=True
        else:gap=raw['cases'][0]['minimum_separating_gap_1ms_mm'];pose=False
        machine=Coordinator('A');first=machine.start(plan(),0,left_clear_confirmed=True)[0];second=machine.receive(first.token,'rotation_complete',1,obs(1,False),left_clear_confirmed=True)[0];issued=machine.receive(second.token,'lower_grip_and_upper_space_ready',2,obs(2,gap=gap,pose=pose),left_clear_confirmed=True);assert not issued and machine.phase==Phase.REGRASP;denials.append(dict(label=label,source=path.relative_to(R).as_posix(),sha256=sha(path),left_access_denied=True,gap_mm=gap,target_pose_confirmed=pose))
    nominal_source=O/'continuous_handoff/review.json';nominal=json.loads(nominal_source.read_bytes());assert nominal['quarter_and_handoff_passed'];v=nominal['dynamic'];tail=v['settled_tail']
    actual_plan=Plan(nominal['candidate_sha256'],'placement-model-v1','lower-grip-86deg-model-v1','nominal-model-world',90,{p.value:600. for p in (Phase.ROTATE,Phase.REGRASP,Phase.APPROACH,Phase.TURN,Phase.RETREAT)})
    machine=Coordinator(actual_plan.entry_grip);first=machine.start(actual_plan,0,left_clear_confirmed=True)[0];second=machine.receive(first.token,'rotation_complete',1,Observation(1,frozenset(range(1,17)),True),left_clear_confirmed=True)[0]
    measured=Observation(2,frozenset(range(1,17)),v['safety_passed'],True,True,tail['opposed_lower_body_contact_fraction']>.8,nominal['quarter_and_handoff_passed'],tail['minimum_separating_plane_gap_1ms_mm'],actual_plan.common_frame)
    admitted=machine.receive(second.token,'lower_grip_and_upper_space_ready',2,measured,left_clear_confirmed=True);assert len(admitted)==1 and machine.phase==Phase.APPROACH
    nominal_admission=dict(source=nominal_source.relative_to(R).as_posix(),sha256=sha(nominal_source),candidate_sha256=nominal['candidate_sha256'],nominal_model_handoff_admitted=True,synthetic_observation_from_saved_simulation_only=True,load_envelope_fully_qualified=nominal['all_nominal_hypothetical_loads_passed'],actual_left_motion_executed=False)
    report=dict(status='offline_temporal_access_protocol_review',synthetic_cycle_only=True,intents=intents,clearance_not_required_during_right_rotation_or_regrasp=True,clearance_required_during_left_approach_turn_retreat=True,next_motion_requires_left_clear_and_matching_primitive_entry=True,saved_candidate_denials=denials,new_nominal_model_admission=nominal_admission,actual_loaded_motion_connection_implemented=False,actual_left_geometry_calibrated=False,protocol_source_sha256=sha(R/'temporal_two_hand_coordinator_20261106.py'),test_source_sha256=sha(R/'test_temporal_two_hand_coordinator_20261106.py'),devices_opened=False,hardware_execution_allowed=False);(O/'temporal_handoff_review.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>윗단 공간을 비우는 시점</title><style>body{font:17px/1.8 system-ui;max-width:960px;margin:30px auto;padding:0 20px;color:#24313c}button{font:inherit;padding:12px;margin:5px;border:1px solid #9bb4c8;border-radius:8px;cursor:pointer}#state{padding:20px;background:#e5edf7;border-radius:12px;min-height:170px}.notice{background:#fff0ce;padding:15px}.flow{display:flex;flex-wrap:wrap;gap:5px}a{color:#145c9e}</style><h1>윗단 공간을 비우는 시점</h1><p>오른손의 전체 회전과 재파지 중에는 윗단 공간을 사용한다. 다른 손이 접근하기 전에 하단을 고정하고, 접근과 윗단 회전, 퇴각이 끝날 때까지 공간을 비운다.</p><p class="notice">아래는 동작 순서의 설명이다. 새 물리 경로가 연결돼 성공했다는 영상이 아니다. 현재 저장 후보 두 개 모두 다른 손의 접근 허가를 받지 못했다.</p><div class="flow"><button data-i="0">1. 전체 회전</button><button data-i="1">2. 재파지</button><button data-i="2">3. 윗단 작업</button><button data-i="3">4. 다음 회전</button></div><div id="state" aria-live="polite"></div><p>약89도 고정 파지는 윗단 공간이 부족하다. 공간을 비운 임시 파지는 약83.6도라 목표 자세가 미달이다. 실제 왼손 접근과 하중도 아직 확인하지 않았다.</p><p><a href="countergrip_progress/index.html">저장된 재파지 시뮬레이션 영상</a> / <a href="temporal_handoff_review.json">순서 검사와 후보 거부 기록</a> / <a href="offline_review.html">전체 진행 상황</a></p><script>const steps=[['전체 회전','윗단 공간을 사용해도 됨','다른 손은 큐브 밖에 머무른다. 이 구간의 회전 완료만으로 다른 손의 접근을 허가하지 않는다.'],['재파지','손가락을 옮긴 뒤 공간 확보','오른손이 하단을 고정하고 목표 자세와 공간 여유를 확인한다. 이 확인이 끝나야 다음 단계로 간다.'],['다른 손의 접근과 회전, 퇴각','윗단 공간을 계속 비워 둠','오른손은 같은 목표를 유지해 큐브 몸통을 잡는다. 다른 손이 완전히 빠지기 전에는 다음 오른손 회전을 시작하지 않는다.'],['다음 전체 회전','윗단 공간을 다시 사용해도 됨','다른 손의 퇴각과 다음 경로의 시작 파지가 확인돼야 한다. 실제 다음 회전 경로는 아직 검증되지 않았다.']];function show(i){const s=steps[i];document.getElementById('state').replaceChildren();for(const [tag,t] of [['h2',s[0]],['strong',s[1]],['p',s[2]]]){const e=document.createElement(tag);e.textContent=t;document.getElementById('state').append(e)}}document.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.i))));show(0)</script></html>''';(O/'temporal_handoff_review.html').write_text(page,encoding='utf-8');print(json.dumps(dict(synthetic_intents=len(intents),qualified_saved_candidates=0,blocked_saved_candidates=len(denials),devices_opened=False,hardware_execution_allowed=False)))
def refresh_nominal_page():
    p=O/'temporal_handoff_review.html';page=p.read_text(encoding='utf-8')
    page=page.replace('아래는 동작 순서의 설명이다. 새 물리 경로가 연결돼 성공했다는 영상이 아니다. 현재 저장 후보 두 개 모두 다른 손의 접근 허가를 받지 못했다.','아래는 기기 없는 동작 순서 설명이다. 새 연속 경로는 기준 모델 한 조건에서 약85.94도 회전 후 하단 접촉과 윗단 공간을 확보했다. 실제 왼손 접근과 윗단 회전을 실행한 결과는 아니다.')
    page=page.replace('약89도 고정 파지는 윗단 공간이 부족하다. 공간을 비운 임시 파지는 약83.6도라 목표 자세가 미달이다. 실제 왼손 접근과 하중도 아직 확인하지 않았다.','이전 약89도 후보는 공간 부족, 약83.6도 후보는 자세 미달로 계속 거부한다. 새 기준 모델 후보는 재파지 뒤 공간0.89mm와 기울기1.69도를 확보해 모의 접근 단계를 허용했다. 가정한 큰 하중 한 방향은 아직 미달이고 실제 왼손 형상과 하중은 확인하지 않았다.')
    page=page.replace('오른손은 같은 목표를 유지해 큐브 몸통을 잡는다.','오른손은 검증된 고정 목표로 큐브 몸통을 잡는다.')
    page=page.replace('<a href="countergrip_progress/index.html">저장된 재파지 시뮬레이션 영상</a>','<a href="continuous_handoff/evidence/index.html">새 연속 경로 영상</a> / <a href="countergrip_progress/index.html">이전 재파지 비교</a>')
    p.write_text(page,encoding='utf-8')
    print(json.dumps(dict(new_nominal_handoff_admitted_in_synthetic_protocol=True,physical_connection_implemented=False)))
if __name__=='__main__':main();refresh_nominal_page()
